import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Empaquetage, signature et registres de plugins","description":"","frontmatter":{"title":"Empaquetage, signature et registres de plugins","docId":"developer.plugins.packaging-registry","translationKey":"developer.plugins.packaging-registry","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4621be5493f2518bff00b4330fcf781ac016761ed8549c118515d6c212fc56cf","translationRevision":"aaa434f8c174fc80dbe3cf587601e05d4ab5f03c308537bd54a6c7e50a8962ae","order":280},"headers":[],"relativePath":"fr/developer/plugins/packaging-registry.md","filePath":"fr/developer/plugins/packaging-registry.md","lastUpdated":1795731074000}`),a={name:`fr/developer/plugins/packaging-registry.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="plugin-packaging-signing-and-registries" tabindex="-1">Empaquetage, signature et registres de plugins <a class="header-anchor" href="#plugin-packaging-signing-and-registries" aria-label="Permalink to “Empaquetage, signature et registres de plugins”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objectif et prérequis”">​</a></h2><p>Distribuer un paquet dont les octets, l’autorité de l’éditeur et la compatibilité de l’hôte peuvent être vérifiés indépendamment. Commencez avec un plugin validé et une cible prise en charge. La signature nécessite des clés privées d’auteur conservées hors du dépôt ; la délégation racine du registre est une responsabilité distincte de l’opérateur.</p><h2 id="prepare-a-reviewable-archive" tabindex="-1">Préparer une archive à examiner <a class="header-anchor" href="#prepare-a-reviewable-archive" aria-label="Permalink to “Préparer une archive à examiner”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publisher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys</span></span></code></pre></div><p><code>build</code> compile le paquet et crée des archives <code>.plugin</code>. L’entrée du manifeste, les ressources, langues, sorties d’interface et dépendances d’exécution pertinentes sont incluses avec <code>checksums.json</code>. Les compilations natives/processus nécessitent une ressource cible compatible ; les paquets uniquement JavaScript restent portables jusqu’à ce que des extensions natives ou fonctions de plateforme les contraignent.</p><p>Pour une archive compilée existante, utilisez des chemins de fichiers exacts plutôt qu’un joker non examiné :</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.key.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span></span></code></pre></div><p>Remplacez le nom de l’archive par la sortie réelle propre à la cible de compilation. La signature couvre les sommes de contrôle, qui couvrent les fichiers du paquet. Les clés publiques peuvent être partagées ; les fichiers de clés privées ne doivent entrer ni dans le contrôle de version ni dans les journaux.</p><h2 id="trust-and-update-policy" tabindex="-1">Confiance et politique de mise à jour <a class="header-anchor" href="#trust-and-update-policy" aria-label="Permalink to “Confiance et politique de mise à jour”">​</a></h2><p>Le protocole du registre statique possède une autorité signée par la racine et des clés déléguées d’index/éditeur. L’approbation de l’espace de noms d’un éditeur est distincte de l’intégrité du paquet, et une empreinte du catalogue Cloud ne remplace aucune des deux chaînes de signature. Le résolveur vérifie canal, moteur, schéma/protocole/ABI, environnement d’exécution et cible. Les versions retirées, révoquées ou incompatibles restent inéligibles même lorsque leur hachage correspond.</p><p>L’installation par l’hôte présente d’abord un examen. Les mises à jour automatiques nécessitent une politique autorisée, un paquet non épinglé, un éditeur signé compatible et aucune nouvelle autorité ; des permissions élargies exigent un examen. L’installation depuis le catalogue Cloud du produit est distincte de la création de registre statique de bas niveau, et les parcours produit ordinaires rejettent les URL de paquets distants arbitraires.</p><h2 id="expected-result-recovery-and-verification" tabindex="-1">Résultat attendu, récupération et vérification <a class="header-anchor" href="#expected-result-recovery-and-verification" aria-label="Permalink to “Résultat attendu, récupération et vérification”">​</a></h2><p>L’installateur peut vérifier les octets avant d’appliquer un paquet examiné et conserver un état de retour arrière/récupération. La préparation de développement échappe à la gestion de l’installateur. En cas d’échec de confiance, réparez la délégation ou les métadonnées de l’éditeur plutôt que d’utiliser normalement des options de contournement non signé. En cas de démarrage incertain, arrêtez le remplacement et résolvez le résultat conservé.</p><p>Utilisez <code>bun scripts/task.ts rust test -p tiktools-plugin-package --locked</code> et les tests du registre pour les fixtures hors ligne. Le <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-package/src" target="_blank" rel="noreferrer">vérificateur de paquets</a> et le <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-plugin-registry/src/model.rs" target="_blank" rel="noreferrer">modèle du registre</a> définissent les formats techniques ; l’infrastructure de publication nécessite une validation distincte de l’opérateur.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Détails de fonctionnement”">​</a></h2><p>Interprétez le JSON de vérification, pas seulement le code de sortie. <code>verify</code> peut réussir avec <code>signature.status</code> égal à <code>unsigned</code> ou <code>untrusted</code>. N’acceptez que <code>verified</code> avec ID de paquet, éditeur et clé attendus, puis vérifiez la politique de distribution. Une clé locale <code>--trust</code> prouve cette signature locale, pas la délégation du registre ni le namespace. Les checksums seuls ne prouvent ni autorité ni confiance updater. L’automatisation ci-dessous doit échouer sur tout résultat inattendu.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verification.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;const r = await Bun.file(&quot;verification.json&quot;).json(); if (r.signature?.status !== &quot;verified&quot; || r.id !== &quot;acme.hello&quot; || r.signature.publisher !== &quot;acme&quot; || r.signature.keyId !== &quot;acme-1&quot;) throw new Error(&quot;Package trust did not match policy&quot;);&#39;</span></span></code></pre></div><h2 id="command-line-operations" tabindex="-1">Opérations en ligne de commande <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Opérations en ligne de commande”">​</a></h2><p>Chaque opération de ce guide est aussi disponible depuis la CLI — hors ligne, scriptable et adaptée aux agents. Les lignes d&#39;usage sont la syntaxe du parseur et restent en anglais dans toutes les langues.</p><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools publisher list</code></td><td>lister les espaces d&#39;éditeur</td></tr><tr><td><code>tiktools publisher create &lt;namespace&gt;</code></td><td>créer un espace d&#39;éditeur</td></tr><tr><td><code>tiktools publisher delete &lt;namespace-or-publisher-id&gt;</code></td><td>supprimer un espace ou un éditeur <strong>destructif</strong></td></tr><tr><td><code>tiktools publisher keys &lt;publisher-id&gt;</code></td><td>lister les clés de signature d&#39;un éditeur</td></tr><tr><td><code>tiktools publisher enroll &lt;publisher-id&gt; [--key-id &lt;id&gt;]</code></td><td>inscrire une clé d&#39;éditeur ; lit le mot de passe du backend depuis stdin</td></tr><tr><td><code>tiktools publisher upload &lt;publisher-id&gt; &lt;path&gt;</code></td><td>téléverser un paquet de plugin</td></tr><tr><td><code>tiktools publisher submit &lt;upload-id&gt; &lt;publisher-key-id&gt; &lt;plugin-id&gt; &lt;version&gt; [--target any]</code></td><td>soumettre un téléversement pour révision</td></tr><tr><td><code>tiktools publisher release &lt;release-id&gt;</code></td><td>créer une release</td></tr><tr><td><code>tiktools publisher publish &lt;release-id&gt;</code></td><td>publier une release</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>lister les registres configurés</td></tr><tr><td><code>tiktools registry refresh</code></td><td>actualiser les métadonnées du registre</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>afficher un paquet du registre</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>rechercher dans le catalogue cloud</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>page de résumés du catalogue cloud</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>versions d&#39;un paquet du catalogue cloud</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>capacités de pagination du catalogue cloud</td></tr><tr><td><code>tiktools registry defaults</code></td><td>configuration par défaut du registre</td></tr></tbody></table><p>Consultez la <a href="./../cli.html">référence complète des commandes</a> pour les conventions, la sortie JSON et les marqueurs d’opérations destructives.</p>`,23)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};